    n, k = map(int, input().split())

    # dp[i][j] = number of good sequences of length i ending with j
    dp = [[0] * (n + 1) for _ in range(k + 1)]

    # Base case: sequences of length 1
    for j in range(1, n + 1):
        dp[1][j] = 1

    # Fill the dp table for sequences of length 2 to k
    for i in range(2, k + 1):
        for j in range(1, n + 1):
            # For sequence ending with j, we can extend any previous sequence ending with a divisor of j
            for prev in range(1, j + 1):
                if j % prev == 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][prev]) % MOD

    # Sum all sequences of length k
