def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_all_hcf_factors(x, y):
    g = gcd(x, y)
    factors = []
    # Find all divisors of the GCD
    i = 1
    while i * i <= g:
        if g % i == 0:
            factors.append(i)
            if i != g // i:
                factors.append(g // i)
        i += 1
    factors.sort(reverse=True)
    return factors

def kth_hcf(x, y, k):
    hcf_factors = get_all_hcf_factors(x, y)
    if k > len(hcf_factors):
        return None
    return hcf_factors[k - 1]

