import math

def get_hcf_divisors(x, y):
    # Find the GCD of x and y
    g = math.gcd(x, y)
    if g == 0:
        return []

    # Find all divisors of g
    divisors = []
    for i in range(1, int(math.isqrt(g)) + 1):
        if g % i == 0:
            divisors.append(i)
            if i != g // i:
                divisors.append(g // i)

    # Sort in descending order
    divisors.sort(reverse=True)
    return divisors

def kth_hcf(x, y, k):
    divisors = get_hcf_divisors(x, y)
    if k > len(divisors):
        return None
    return divisors[k - 1]

